//   ড্রাই-রান:  node scripts/populateWellnessGuides.js
//   আসল write: node scripts/populateWellnessGuides.js --confirm
//   এডিট/overwrite: node scripts/populateWellnessGuides.js --confirm --force

import { initializeApp, cert } from "firebase-admin/app";
import { getFirestore, FieldValue } from "firebase-admin/firestore";
import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import path from "path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const CONFIRM = process.argv.includes("--confirm");
const FORCE = process.argv.includes("--force");

const keyPath = process.env.GOOGLE_APPLICATION_CREDENTIALS || path.join(__dirname, "serviceAccountKey.json");

let serviceAccount;
try {
  serviceAccount = JSON.parse(readFileSync(keyPath, "utf8"));
} catch (e) {
  console.error(`❌ Service account key পাওয়া যায়নি: ${keyPath}`);
  console.error("   Firebase Console → Project Settings → Service Accounts → Generate new private key");
  console.error("   ফাইলটা scripts/serviceAccountKey.json নামে রাখুন।");
  process.exit(1);
}

initializeApp({ credential: cert(serviceAccount) });
const db = getFirestore();

function slugify(s) {
  return String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}
function docIdFor(entry) {
  const tail = entry.code ? slugify(entry.code) : slugify(entry.title);
  return `${entry.category}-${tail}`.slice(0, 120);
}

// body-র শব্দ-সংখ্যা: [MORE] ও রেফারেন্স-অংশ ("▌ রেফারেন্স" থেকে শেষ) বাদ; শুধু অক্ষর/অঙ্কযুক্ত টোকেন গোনা হয়।
const MIN_WORDS = 500;
function bodyWordCount(body) {
  let text = String(body || "").replace("[MORE]", " ");
  const refAt = text.search(/^▌\s*রেফারেন্স/m);
  if (refAt !== -1) text = text.slice(0, refAt);
  return text.split(/\s+/).filter((t) => /[\p{L}\p{N}]/u.test(t)).length;
}

